INSERT INTO "pending_actions" VALUES('QT0IE9Ae','mission_qualification','{"source": "lecercle", "external_id": "b7b25a1f27121dad", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/senior-business-analyst-investment-asset-change-6-mois/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Alerte générique du Cercle sans réel contenu : le texte affiché mentionne \"Directeur Général - Groupe de Grande Dis[tribution]\" mais est tronqué et ne décrit ni périmètre, ni client, ni durée, ni TJM. Le lien pointe même vers une mission \"Senior Business Analyst Investment/Asset Change\" sans rapport avec un mandat DSI/CTO.", "motifs": ["<motifs>Contenu de l''annonce quasi inexistant : pas de rôle décrit, pas de périmètre, pas de durée</motifs>\n<motifs>Incohérence entre l''intitulé (DSI/Groupe) et le lien fourni (Senior Business Analyst Investment/Asset Change) : suspicion d''alerte mal indexée ou de mauvais mapping</motifs>\n<motifs>Aucun TJM affiché ; sous plancher EMT tant que non confirmé</motifs>\n<motifs>Aucun élément permettant de juger le registre (technique/opérationnel/exécutif) ni le rôle attendu (mandat vs consultant pair)</motifs>\n</motifs>\n<informations_manquantes>\n<informations_manquantes>Descriptif réel du poste (périmètre, rattachement, équipe, enjeux)</informations_manquantes>\n<informations_manquantes>Durée et date de démarrage</informations_manquantes>\n<informations_manquantes>TJM proposé</informations_manquantes>\n<informations_manquantes>Confirmation que le lien correspond bien à l''intitulé DSI/Groupe (le lien actuel renvoie à une mission Business Analyst)</informations_manquantes>\n<informations_manquantes>Secteur et taille de l''entreprise cliente</informations_manquantes>\n</informations_manquantes>\n<questions>\n<questions>Pouvez-vous confirmer le descriptif complet du poste \"Directeur des Systèmes d''Information - Groupe\" (périmètre, rattachement, enjeux) ? Le lien transmis semble renvoyer à une autre mission.</questions>\n<questions>Quel est le TJM proposé pour ce mandat ?</questions>\n<questions>Quelle est la durée du mandat et la date de démarrage souhaitée ?</questions>\n<questions>Le rôle est-il un mandat de DSI avec autorité de décision, ou un poste de conseil/support sans autorité directe ?</questions>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJe suis manager de transition DSI/CTO, dernières missions en pilotage de transformation IT (process ITIL chez Saint-Gobain, PMO transformation digitale chez Maguin-Promill) — je me positionne sur des mandats exécutifs DSI/DOSI Groupe en France.\n\nLe contenu de votre alerte \"Directeur des Systèmes d''Information - Groupe\" reçu ne comporte pas de descriptif exploitable, et le lien associé semble pointer vers une autre mission (Senior Business Analyst Investment/Asset Change). Seriez-vous disponible pour un échange court afin de clarifier le poste réel derrière cette alerte ?\n\nQuelques points à préciser pour avancer :\n- Le descriptif complet du mandat (périmètre, rattachement, enjeux)\n- La durée et la date de démarrage envisagées\n- Le TJM proposé\n\nMerci et au plaisir d''échanger.\n\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles>\n<signaux_faibles>Lien de l''annonce incohérent avec l''intitulé (mission Business Analyst au lieu de DSI Groupe)</signaux_faibles>\n<signaux_faibles>Contenu tronqué / alerte automatique sans substance exploitable</signaux_faibles>\n</signaux_faibles>"]}, "decision": "no_go"}','executed',NULL,'2026-08-12 06:19:44','2026-08-13 03:18:40',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('M4bXUQ2V','mission_qualification','{"source": "lecercle", "external_id": "7fceb0766ea04ae1", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/responsable-adjoint-comptabilite-generale-groupe-international-de-la-distribution-4-mois-minimum/", "contact_email": null, "qualification": {"synthese": "Notification d''alerte automatique du Cercle listant une mission « Directeur des Systèmes d''Information - Groupe » sans quasiment aucun contenu exploitable : le texte fourni est tronqué, mélange un intitulé DSI avec un fragment « Directeur Général - Groupe de Grande Dis... », et ne précise ni client, ni périmètre, ni TJM, ni durée, ni lieu.", "motifs": ["<item>Le contenu de l''annonce est un fragment tronqué et incohérent (mélange DSI / DG / Grande Distribution), impossible à qualifier en l''état</item>\n<item>Aucun TJM affiché : le plancher EMT net (850€/j) ne peut même pas être vérifié</item>\n<item>Aucune information sur le périmètre, la durée, le rôle ou le contexte de transformation (carve-out, fusion, dette technique...) qui définit le profil cible INOVOPS</item>\n<item>Rien n''indique s''il s''agit d''un mandat exécutif DSI ou d''un rôle de consultant pair — point décisif non trenchable ici</item>\n</motifs>\n<questions>\n<item>Quel est le TJM proposé pour cette mission ?</item>\n<item>Quel est le périmètre exact du mandat : DSI/CTO en mandat exécutif avec autorité de décision, ou mission de conseil/support ?</item>\n<item>Quelle est la durée prévisionnelle et la date de démarrage souhaitée ?</item>\n<item>Quel est le contexte de la mission (transformation, carve-out, fusion, audit, dette technique) et la taille de l''organisation ?</item>\n<item>Le poste est-il basé en France, et sous quel format (présentiel/hybride) ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJe me positionne en tant que manager de transition DSI/CTO sur des mandats exécutifs de 6 à 9 mois, typiquement dans des contextes de transformation post-événement (carve-out, fusion, dette technique critique, perte de confiance des équipes IT/métiers) — récemment sur des missions de pilotage IT et transformation digitale (Saint-Gobain, MAGUIN-PROMILL).\n\nVotre annonce évoque un poste de Directeur des Systèmes d''Information mais le contenu transmis est très partiel. Seriez-vous disponible pour un échange court afin de clarifier le périmètre ?\n\nQuelques points à préciser à cette occasion :\n- le TJM proposé,\n- la nature du mandat (exécutif avec autorité de décision, ou rôle de conseil),\n- la durée et le contexte de la mission (transformation, taille de l''organisation),\n- le format (présentiel/hybride) et la localisation.\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles>\n<item>Annonce quasi vide de contenu exploitable — pas d''accroche métier, pas de contexte, pas de rôle défini</item>\n<item>Texte fourni semble être un extrait tronqué/mal découpé d''une liste de plusieurs offres, pas une fiche de mission dédiée</item>\n</signaux_faibles>\n<recommandation>poursuivre_sous_reserve</recommandation>"]}, "decision": "no_go"}','executed',NULL,'2026-08-12 06:20:01','2026-08-13 03:18:20',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('guEP8k3C','mission_qualification','{"source": "lecercle", "external_id": "ef0b69a063f726bd", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/lead-product-manager-acteur-europeen-de-lassurance-4-a-6-mois-800-e-a-850-e-par-jour/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Ceci est un e-mail d''alerte automatique du Cercle listant des correspondances à une alerte \"DSI Groupe\" — pas une offre de mission qualifiée. Le seul intitulé visible dans le contenu fourni (\"Directeur Général - Groupe de Grande Dis[tribution]\") est tronqué et ne décrit ni périmètre, ni durée, ni TJM, ni client.", "motifs": ["<item>Le contenu transmis est une notification d''alerte, pas le corps d''une annonce de mission — aucun descriptif de poste exploitable</item>\n<item>Aucun TJM affiché, aucune durée, aucun lieu, aucune date de démarrage</item>\n<item>Le titre visible dans l''extrait renvoie même à un poste de Directeur Général, pas de DSI — signe que le contenu de l''annonce n''a pas été correctement récupéré</item>\n<item>Rien ne permet d''évaluer le registre attendu (technique/opérationnel/exécutif) ni le rôle (mandat vs pair)</item>\n</motifs>\n<item_unused></item_unused>\n<parameter name=\"questions\">\n<item>Pouvez-vous partager le descriptif complet de la mission DSI Groupe (périmètre, durée, TJM, localisation) ?</item>\n<item>Le poste correspond-il à un mandat de DSI/CTO avec autorité de décision, ou à une mission de conseil/PMO sans autorité exécutive ?</item>\n<item>Quel est le trigger de la mission (carve-out, fusion, dette technique, audit défavorable) et la taille du groupe concerné ?</item>"], "brouillon_reponse": "Bonjour,\n\nJe suis intéressé par votre alerte \"Directeur des Systèmes d''Information - Groupe\". Je suis manager de transition DSI/CTO, avec des mandats récents sur des problématiques de transformation IT (PMO transformation digitale, structuration IT, pilotage de dette technique) chez des groupes en environnement industriel et services.\n\nLe contenu que j''ai reçu ne comporte pas le descriptif détaillé du poste — pourriez-vous me transmettre le brief complet (périmètre, durée, TJM, contexte) afin que je puisse évaluer l''adéquation avec mon profil ?\n\nJe reste disponible pour un échange rapide si le mandat correspond à un rôle exécutif avec autorité de décision.\n\nCordialement,\nJayson Angele", "informations_manquantes": ["<item>Descriptif du poste (le contenu fourni est une notification d''alerte, pas l''annonce elle-même)</item>\n<item>TJM</item>\n<item>Durée et date de démarrage</item>\n<item>Lieu / modalité (site, hybride, remote)</item>\n<item>Rôle attendu : mandat exécutif ou mission de conseil</item>"], "signaux_faibles": ["<item>L''extrait de contenu fait référence à un poste de \"Directeur Général - Groupe de Grande Dis[tribution]\", incohérent avec l''intitulé \"DSI Groupe\" — signe possible d''un problème de récupération de contenu côté canal</item>\n<item>Aucune information de fond permettant de juger du registre ou de l''autorité du poste</item>"], "registre": "indetermine", "role_attendu": "indetermine"}, "decision": "no_go"}','executed',NULL,'2026-08-12 06:20:18','2026-08-13 03:16:04',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('rUwJLch7','reply_mail','{"to": "", "subject": "Relance 2I CONNECT - DSI de transition Montreuil", "body": "Madame, Monsieur,\n\nJe fais suite à ma candidature au poste de DSI de transition, proposée sur Free-Work le 5 août dernier au titre du mandat 2I CONNECT à Montreuil.\n\nJe reste mobilisé sur cette mission et souhaiterais connaître l''état d''avancement de votre processus de sélection.\n\nPouvez-vous me confirmer si mon profil reste en considération pour ce poste ?\n\nJe reste à votre disposition pour un échange.\n\nCordialement,\nJayson Angele", "relance_task_id": "6a731209323a46266", "dossier": {"intitule": "DSI de transition Montreuil", "source": "Relance 2I CONNECT", "canal": "Canal de relance : candidature deposee sur Free-Work (offre ''DSI de transition'', 2I CONNECT) le 05/08/2026 -> relancer par le canal de la plateforme, ou par email si un interlocuteur 2I CONNECT s''est identifie entre-temp", "url": "", "contact": "", "envoyee_le": "05/08/2026", "cadrage": ""}}','rejected',NULL,'2026-08-12 06:54:33','2026-08-12 07:04:12',NULL,'Exécution manuel',NULL);
INSERT INTO "pending_actions" VALUES('bzX5e1J5','mission_qualification','{"source": "lecercle", "external_id": "fba26025e1543df1", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/data-governance-analyst-groupe-financier-international-24-mois/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Notification d''alerte automatique du Cercle listant un intitulé de mission (\"Directeur des Systèmes d''Information - Groupe\") sans aucun contenu réel : ni client, ni périmètre, ni TJM, ni durée, ni lieu — le texte est tronqué et bascule même sur un autre intitulé (\"Directeur Général - Groupe de Grande Distribution\").", "motifs": ["<item>Le contenu fourni est un fragment d''email d''alerte, pas une fiche de mission : aucune information exploitable sur le poste, le mandat ou les conditions</item>\n<item>Le texte lui-même semble corrompu ou coupé (mélange DSI / Directeur Général Distribution), signe que l''annonce n''a pas été correctement captée</item>\n<item>Aucun TJM affiché alors que le plancher EMT (850€/j net) doit être vérifié avant tout engagement de temps</item>\n<item>Impossible d''évaluer le registre (technique/opérationnel/exécutif) ni le rôle attendu (mandat vs pair) sur la base de ce fragment</item>\n</motifs>\n<parameter name=\"questions\">\n<item>Pouvez-vous partager la fiche de mission complète correspondant à cette alerte DSI - Groupe ?</item>\n<item>Quel est le TJM proposé pour ce mandat ?</item>\n<item>Quel est le périmètre du poste : DSI de filiale, DSI groupe, contexte de transformation (carve-out, fusion, dette technique) ?</item>\n<item>Quelle est la durée du mandat et la date de démarrage envisagée ?</item>\n</questions>\n<parameter name=\"signaux_faibles\">\n<item>Annonce techniquement incomplète / probablement mal extraite (mélange de deux intitulés différents)</item>\n<item>Aucun élément de contexte, de périmètre ou de mandat permettant de juger la nature du poste</item>\n</signaux_faibles>\n<parameter name=\"brouillon_reponse\">Bonjour,\n\nJe suis manager de transition DSI/CTO, avec une pratique récente de la structuration IT et de la conduite de transformation en contexte de dette technique critique et de perte de confiance des équipes métiers (dernières missions : pilotage de processus ITIL chez Saint-Gobain, PMO transformation digitale chez Maguin-Promill). Le profil \"Directeur des Systèmes d''Information - Groupe\" correspond bien à ce type de mandat.\n\nLe contenu que j''ai reçu de votre alerte est cependant très partiel — il ne mentionne ni périmètre, ni TJM, ni durée, ni contexte client. Seriez-vous disponible pour un échange rapide afin de voir si le mandat correspond à mon positionnement ?\n\nQuelques points à préciser à cette occasion :\n- le périmètre exact du poste (DSI de filiale ou de groupe, contexte de transformation)\n- la durée du mandat et la date de démarrage envisagée\n- le TJM proposé\n\nBien cordialement,\nJayson Angele"], "role_attendu": "indetermine", "registre": "indetermine", "informations_manquantes": ["<item>Fiche de mission complète (le texte fourni est un fragment d''alerte tronqué/corrompu)</item>\n<item>TJM proposé</item>\n<item>Périmètre du poste et contexte de transformation</item>\n<item>Durée et date de démarrage</item>\n<item>Lieu / modalité (remote, hybride, onsite)</item>\n</informations_manquantes>\n</invoke>"]}, "decision": "no_go"}','executed',NULL,'2026-08-12 07:10:54','2026-08-13 03:15:43',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('M2r8Lc8v','mission_qualification','{"source": "lecercle", "external_id": "d9cfcc68ad02cace", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/director-of-finance-section-151-officer-services-publics-3-a-6-mois/", "contact_email": null, "qualification": {"synthese": "L''annonce est un simple e-mail d''alerte du Cercle listant plusieurs opportunités correspondant au mot-clé \"DSI - Groupe\" ; le contenu réellement fourni s''arrête après \"Directeur Général - Groupe de Grande Dis[tribution]\" et ne décrit aucun poste, aucun périmètre, aucune durée ni TJM pour une mission DSI.", "motifs": ["<item>Le texte fourni est une notification d''alerte, pas une fiche de mission : aucune description de poste, de périmètre ni d''autorité attendue</item>\n<item>Le lien pointe vers une mission \"Director of Finance / Section 151 Officer - Services Publics\" qui n''a rien à voir avec un poste DSI, signe d''un mismatch entre alerte et contenu réel</item>\n<item>Secteur \"Services Publics\" mentionné dans le lien correspond à un secteur explicitement évité par le positioning INOVOPS</item>\n<item>Aucun TJM affiché, donc aucune vérification possible du plancher EMT (850€/j net)</item>\n</motifs>\n<questions>\n<item>Pouvez-vous confirmer s''il s''agit d''une mission de Directeur des Systèmes d''Information, ou bien de la mission \"Director of Finance / Section 151 Officer\" indiquée par le lien ?</item>\n<item>Quel est le secteur et la taille de l''entreprise cliente concernée ?</item>\n<item>Le mandat est-il un rôle de DSI avec autorité de décision, ou une mission de conseil/accompagnement sans mandat exécutif ?</item>\n<item>Quel est le TJM proposé et la durée du mandat ?</item>\n</questions>\n<brouillon_reponse>Bonjour,\n\nJe vous recontacte suite à votre alerte \"Directeur des Systèmes d''Information - Groupe\". Le lien transmis semble toutefois renvoyer vers une mission \"Director of Finance / Section 151 Officer\" sur le secteur public — pourriez-vous me confirmer de quelle mission il s''agit réellement ?\n\nSi une mission DSI/DOSI est bien disponible : je suis manager de transition spécialisé sur des mandats exécutifs DSI/CTO en contexte de transformation (carve-out, fusion, dette technique critique, perte de confiance des équipes IT), sur des structures de 1 000 à 5 000+ collaborateurs, en industrie, services, santé, banque ou assurance.\n\nSeriez-vous disponible pour un échange court afin de clarifier le poste concerné ?\n\nDans cette attente, pourriez-vous préciser :\n- le périmètre exact du mandat (rôle, autorité de décision) ;\n- le secteur et la taille de l''entreprise cliente ;\n- la durée et le TJM proposés.\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles>\n<item>Le lien fourni ne correspond pas à l''intitulé de l''alerte (mismatch DSI vs Finance/Section 151 Officer secteur public)</item>\n<item>Contenu de l''annonce quasi vide — aucun élément de poste exploitable</item>\n</signaux_faibles>\n<recommandation>ecarter</recommandation>"]}, "decision": "no_go"}','executed',NULL,'2026-08-12 07:11:11','2026-08-13 03:15:25',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('LfIcxatO','mission_qualification','{"source": "lecercle", "external_id": "da73b3863886c5e8", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/directeur-general-groupe-de-grande-distribution/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Annonce quasi vide générée par une alerte : titre \"Directeur Général - Groupe de Grande Distribution\", aucun descriptif de poste, aucun périmètre, aucun TJM affiché, client non nommé, localisation et durée non précisées.", "motifs": ["Le contenu ne décrit aucune mission réelle : pas de périmètre, pas de rattachement, pas de durée, pas de TJM", "Le titre pointe vers un poste de Directeur Général, pas un DSI/CTO — hors positionnement INOVOPS", "Aucun TJM affiché : sous le plancher net EMT de 850 €/j tant que rien n''est confirmé, la mission ne peut être évaluée", "L''annonce ressemble à un teaser d''alerte automatique sans contenu qualifiant, pas à une offre travaillée par un chargé de mission"], "questions": ["Le poste concerne-t-il bien un mandat DSI/CTO/DOSI, ou s''agit-il d''un poste de Direction Générale comme le suggère le titre ?", "Quel est le TJM proposé pour cette mission ?", "Quel est le périmètre du poste : effectif, secteur, contexte de transformation (carve-out, fusion, dette technique, audit) ?", "Quelle est la durée du mandat et la date de démarrage envisagée ?"], "brouillon_reponse": "Bonjour,\n\nJe suis manager de transition DSI/CTO/DOSI, spécialisé sur des mandats exécutifs 6 à 9 mois dans des groupes de 1 000 à 5 000+ collaborateurs (industrie, services, santé, banque, assurance), en particulier sur des contextes de transformation post-événement : carve-out, fusion, dette technique critique, audit défavorable.\n\nVolontiers un échange court pour clarifier le contenu réel de cette mission.\n\nQuelques points à préciser avant d''aller plus loin :\n- Le poste concerne-t-il un mandat DSI/CTO/DOSI, ou s''agit-il d''un poste de Direction Générale comme le titre le suggère ?\n- Quel est le TJM proposé ?\n- Quel est le périmètre (effectif, secteur, contexte de transformation) et la durée du mandat ?\n\nCordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["Titre de l''annonce annonce un poste de Directeur Général, pas de DSI, alors que l''alerte porte sur DSI/CTO", "Contenu tronqué/vide, typique d''une alerte automatique sans validation humaine du contenu", "Aucun élément permettant de vérifier l''adéquation avec le positionnement exécutif recherché"], "informations_manquantes": ["Nature exacte du poste (DSI vs DG)", "TJM", "Client, secteur, taille de l''entreprise", "Durée et date de démarrage", "Contexte de la mission (trigger de transformation)"]}, "decision": "no_go"}','executed',NULL,'2026-08-12 07:11:25','2026-08-13 03:15:09',NULL,NULL,NULL);
