INSERT INTO "pending_actions" VALUES('dPOG_yUd','mission_qualification','{"source": "lecercle", "external_id": "fb60db74f22b248b", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/asset-management-expert-groupe-international-4-a-6-mois/", "contact_email": null, "qualification": {"synthese": "Cette annonce n''est pas une mission mais une notification d''alerte du Cercle : le seul intitulé exploitable évoque une mission \"SI/IT Principal AI Engineer / Architect - Groupe - 6 mois\", sans contexte client, périmètre, lieu, TJM ni date de démarrage.", "motifs": ["<item>L''intitulé \"Principal AI Engineer / Architect\" pointe vers un rôle technique/architecture IA, pas vers un mandat DSI/CTO exécutif</item>\n<item>Aucun élément de contexte (trigger de transformation, taille d''entreprise, secteur) permettant de vérifier l''adéquation avec le positionnement Core INOVOPS</item>\n<item>TJM non affiché : à ce stade normal sur canal EMT, le plancher net à défendre reste 850 €/j</item>\n<item>Le contenu fourni est quasi vide — c''est une notification d''alerte, pas une fiche de poste</item>\n</motifs>\n<informations_manquantes>\n<item>Nature exacte du rôle : s''agit-il d''un mandat de pilotage IT/DSI ou d''un poste d''architecte/ingénieur IA individuel contributeur</item>\n<item>Contexte de transformation (carve-out, fusion, dette technique, audit défavorable...)</item>\n<item>Taille et secteur de l''entreprise cliente</item>\n<item>Durée précise, date de démarrage, lieu</item>\n<item>TJM proposé</item>\n<item>Rattachement hiérarchique et niveau d''autorité du rôle</item>\n</informations_manquantes>\n<questions>\n<item>Pouvez-vous préciser le périmètre exact du rôle \"Principal AI Engineer / Architect\" — s''agit-il d''un mandat de direction IT ou d''un rôle d''expert technique individuel contributeur ?</item>\n<item>Quel est le contexte de la mission (transformation, projet de croissance, remplacement) et à qui le poste est-il rattaché ?</item>\n<item>Quel est le secteur et la taille du groupe concerné, et quel est le lieu de la mission (présentiel/hybride) ?</item>\n<item>Quel est le TJM proposé pour cette mission ?</item>\n</questions>\n<brouillon_reponse>Bonjour,\n\nJ''ai piloté des transformations IT en contexte de groupe multi-sites, avec structuration d''équipes techniques et pilotage de la dette technologique — récemment chez Saint-Gobain (process ITIL, 6 mois) et MAGUIN-PROMILL (PMO transformation digitale). Je serais intéressé d''échanger sur la mission \"Principal AI Engineer / Architect - Groupe - 6 mois\" pour comprendre si elle correspond à mon profil.\n\nSeriez-vous disponible pour un échange rapide cette semaine ?\n\nQuelques points à préciser en amont :\n- Le rôle attendu est-il un mandat de pilotage/direction IT, ou un poste d''expert technique individuel contributeur ?\n- Quel est le contexte de la mission (transformation, croissance, remplacement) et le rattachement hiérarchique ?\n- Secteur, taille du groupe et lieu de la mission ?\n- Quel TJM est proposé sur ce mandat ?\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles\">\n<item>L''intitulé technique \"AI Engineer / Architect\" est en tension avec le positionnement Core INOVOPS (mandat exécutif DSI/CTO) — risque de rôle de pair technique plutôt que mandat de direction</item>\n<item>Annonce quasi vide de contenu : impossible de juger du registre (technique/opérationnel/exécutif) avant clarification</item>\n</signaux_faibles>\n<recommandation>poursuivre_sous_reserve</recommandation>"]}, "decision": "no_go"}','executed',NULL,'2026-08-14 06:19:56','2026-08-18 19:22:50',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('f3mnV881','mission_qualification','{"source": "lecercle", "external_id": "f24dc47db55748f7", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/responsable-qualite-industrie-alimentaire-ingredients-naturels-6-mois/", "contact_email": null, "qualification": {"synthese": "Notification d''alerte Le Cercle quasi vide : le titre affiché ne correspond même pas à l''alerte \"DSI Groupe\" mais mentionne un poste distinct (\"Principal AI Engineer / Architect - Groupe - 6 mois\"). Aucun contexte client, aucun périmètre, aucun TJM affiché — seul le plancher EMT (850 €/j) est connu par défaut.", "motifs": ["<item>Le contenu ne décrit aucun poste exploitable : pas de mission, pas de responsabilités, pas d''autorité décrite</item>\n<item>Incohérence entre l''intitulé de l''alerte (DSI Groupe) et le titre de la mission listée (Principal AI Engineer / Architect) — probable mauvais matching d''alerte ou erreur du canal</item>\n<item>Aucun TJM affiché, seul le plancher EMT (850 €/j net) s''applique par défaut, ce qui n''est pas un motif d''écartement en soi</item>\n<item>Impossible de statuer sur le registre (technique/opérationnel/exécutif) ou le rôle attendu (mandat vs pair) avec si peu d''information</item>\n</motifs>\n<parameter name=\"signaux_faibles\">\n<item>Le poste affiché (\"Principal AI Engineer / Architect\") est un rôle technique individuel contributeur, potentiellement très éloigné du positionnement DSI/CTO/DOSI exécutif visé par Jay</item>\n<item>Notification générique de type \"alerte\", sans lien direct clair vers une fiche de poste détaillée exploitable</item>\n</signaux_faibles>\n<parameter name=\"questions\">\n<item>Pouvez-vous confirmer l''intitulé exact et le périmètre de la mission — s''agit-il d''un mandat DSI/CTO ou d''un poste d''architecte/ingénieur IA senior ?</item>\n<item>Quel est le niveau d''autorité attendu sur cette mission : pilotage exécutif avec décision, ou contribution technique/expertise sans mandat de management ?</item>\n<item>Quel est le secteur d''activité et la taille de l''organisation cliente ?</item>\n<item>Quelle est la durée exacte et la date de démarrage envisagée ?</item>\n<item>Quel TJM le cabinet propose-t-il sur ce mandat ?</item>\n</questions>\n<parameter name=\"brouillon_reponse\">Bonjour,\n\nJe suis manager de transition DSI/CTO, avec des mandats récents en pilotage IT (transformation, gouvernance, structuration d''équipes) sur des organisations en transition. Je note que l''intitulé transmis mentionne un poste d''architecte/ingénieur IA, ce qui semble différent de l''alerte DSI Groupe à laquelle j''étais inscrit — je voulais donc clarifier avant d''aller plus loin.\n\nSeriez-vous disponible pour un échange rapide afin de préciser le périmètre réel de la mission ?\n\nQuelques points à clarifier de mon côté :\n- l''intitulé et le rôle exact recherchés (DSI/CTO exécutif ou expertise technique IA/architecture) ;\n- le niveau d''autorité attendu (mandat de management avec décision, ou contribution/conseil) ;\n- le secteur, la taille de l''organisation et la durée envisagée ;\n- le TJM proposé sur ce mandat.\n\nCordialement,\nJayson Angele"], "role_attendu": "indetermine", "registre": "indetermine", "recommandation": "poursuivre_sous_reserve"}, "decision": "no_go"}','executed',NULL,'2026-08-14 06:20:12','2026-08-18 19:22:48',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('pMQJKQ19','mission_qualification','{"source": "lecercle", "external_id": "e21da00bc784adf0", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/charge-des-verifications-mecaniques-groupe-2-mois/", "contact_email": null, "qualification": {"synthese": "L''annonce n''est pas une mission mais un e-mail d''alerte automatique du Cercle listant un intitulé de mission (\"Principal AI Engineer / Architect - Groupe - 6 mois\") sans aucun descriptif de poste, périmètre, client, ni conditions.", "motifs": ["Le contenu fourni est une notification d''alerte, pas une fiche de mission : aucun descriptif de poste", "L''intitulé capté (Principal AI Engineer / Architect) est hors profil DSI/CTO de transition — registre technique pointu, pas un mandat exécutif", "Aucune information sur le rôle, l''autorité, le secteur ou la durée réelle du mandat", "TJM non affiché ; plancher EMT à 850 €/j à rappeler si un échange s''engage"], "questions": ["Pouvez-vous partager la fiche de mission complète correspondant à cet intitulé ?", "Le poste s''inscrit-il dans un mandat de direction (DSI/CTO) ou dans un rôle de contribution technique (architecte/ingénieur IA) ?", "Quel est le périmètre d''intervention : équipe à manager, budget, décisions attendues ?", "Quel est le TJM proposé sur ce mandat ?"], "brouillon_reponse": "Bonjour,\n\nJe fais du management de transition DSI/CTO sur des mandats de transformation post-événement (carve-out, fusion, dette technique critique, remédiation post-audit), en environnements industrie/services/santé/banque-assurance sur des groupes de 1 000 à 5 000+ collaborateurs.\n\nL''alerte que vous m''avez transmise mentionne un intitulé \"Principal AI Engineer / Architect - Groupe - 6 mois\" mais sans fiche de mission jointe : je ne peux pas encore me positionner dessus.\n\nPourriez-vous me faire parvenir le descriptif complet ? Je souhaiterais notamment préciser : s''agit-il d''un mandat de direction avec autorité de décision, ou d''un rôle de contribution technique/architecture ? Quel est le périmètre exact (équipe, budget, gouvernance) et le TJM envisagé ?\n\nDans l''attente de votre retour pour évaluer l''adéquation avec mon positionnement.\n\nCordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["Intitulé technique (Principal AI Engineer / Architect) incompatible a priori avec un mandat exécutif DSI/CTO", "Contenu quasi vide : simple notification d''alerte, pas une offre qualifiée"], "informations_manquantes": ["Descriptif complet du poste", "Client / secteur", "Périmètre d''autorité et de décision", "Durée exacte et date de démarrage", "TJM proposé", "Lieu de la mission"]}, "decision": "no_go"}','executed',NULL,'2026-08-14 06:20:27','2026-08-18 19:22:44',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('lA8z6oYz','mission_qualification','{"source": "free-work", "external_id": "e13d42f2ee22f7e8", "titre": "Directeur de Projet ERP / AMOA Senior Transformation ERP/be", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjMHGaZAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"synthese": "Poste de Directeur de Projet ERP / AMOA Senior sur transformation ERP, à Paris, client non nommé, à 600 €/j — annonce très pauvre en contenu (aucun périmètre projet, durée, secteur client ni contexte de transformation détaillés au-delà de l''intitulé).", "motifs": ["<item>Rôle décrit comme \"Directeur de Projet ERP / AMOA\" — registre projet/AMOA, pas mandat exécutif DSI/CTO avec autorité de transformation post-événement, cœur de cible INOVOPS</item>\n<item>Tarif affiché 600 €/j, sous le plancher board net de 750 €/j — à mentionner mais pas motif d''écartement en soi</item>\n<item>Annonce quasiment vide : aucune information sur le secteur, la taille de l''entreprise, le déclencheur (carve-out, fusion, dette technique...), la durée ni le périmètre exact du projet ERP</item>\n<item>Canal board (free-work), donc absence de nom client normale et non disqualifiante</item>\n</motifs>\n<signaux_faibles>\n<item>Intitulé \"AMOA Senior\" évoque un rôle de contributeur/pair sur le projet ERP plutôt qu''un mandat de management avec autorité décisionnelle</item>\n<item>Aucune mention de posture exécutive, de sponsor ni de mandat — écart net avec le positionnement interim DSI/CTO visé</item>\n</signaux_faibles>\n<questions>\n<item>Quel est le rôle exact attendu : pilotage du programme ERP avec autorité de décision, ou contribution AMOA en appui d''un chef de projet interne ?</item>\n<item>Quel est le secteur d''activité et la taille de l''entreprise cliente ?</item>\n<item>Quelle est la durée prévisionnelle de la mission et la date de démarrage souhaitée ?</item>\n<item>Le tarif de 600 €/j est-il négociable selon le profil et l''expérience proposée ?</item>\n<item>Quel est le contexte de la transformation ERP : refonte, migration, carve-out, fusion ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJ''ai piloté des transformations IT en contexte de transformation digitale et de structuration de programmes (PMO transformation Digitale chez MAGUIN-PROMILL, pilotage de processus ITIL chez Saint-Gobain), avec une pratique de cadrage AMOA et de coordination de projets transverses.\n\nSeriez-vous disponible pour un échange rapide afin de voir si le profil correspond à votre besoin ?\n\nPour affiner, pourriez-vous préciser :\n- le rôle exact attendu sur ce projet ERP (pilotage avec autorité de décision ou contribution AMOA en appui) ;\n- le secteur et la taille de l''entreprise cliente ;\n- la durée prévisionnelle et la date de démarrage ;\n- le contexte de la transformation (refonte, migration, fusion) ;\n- une marge de discussion possible sur le TJM de 600 €/j.\n\nCordialement,\nJayson Angele"], "role_attendu": "consultant_pair", "recommandation": "poursuivre_sous_reserve", "registre": "operationnel"}, "decision": "no_go"}','executed',NULL,'2026-08-14 07:08:00','2026-08-18 19:22:38',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('12GtLNgb','mission_qualification','{"source": "free-work", "external_id": "91dd93e7680e03d3", "titre": "Directeur de Projet Cybersécurité H/F", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjLEJ97AAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Annonce quasi vide : poste de Directeur de Projet Cybersécurité à Paris, client non nommé, durée et date de démarrage non précisées, tarif affiché 650 €/j sur un board freelance.", "motifs": ["Intitulé ''Directeur de Projet Cybersécurité'' correspond à un rôle projet/PMO, pas à un mandat exécutif DSI/CTO — hors positionnement Core INOVOPS", "TJM affiché 650 €/j, sous le plancher board net de 750 €/j (mention factuelle, pas motif suffisant seul)", "Annonce sans aucun contenu sur le périmètre, l''autorité, la durée ou le contexte client — impossible d''évaluer le registre réel", "Le sujet cybersécurité ne recoupe pas l''expertise infra/IT ops/transformation organisationnelle mise en avant par Jay"], "questions": ["Quel est le périmètre exact du poste : gestion de projet cybersécurité, ou pilotage d''une DSI/RSSI avec mandat de décision ?", "Qui est le sponsor côté client (DSI, RSSI, direction générale) et quelle est l''autorité réelle attachée au poste ?", "Quelle est la durée prévisionnelle de la mission et la date de démarrage souhaitée ?", "Le tarif de 650 €/j est-il négociable selon profil et séniorité ?"], "brouillon_reponse": "Bonjour,\n\nJ''ai piloté des transformations IT incluant des volets sécurité et mise en conformité (structuration SI, gestion de dette technique, remédiation post-audit) dans le cadre de mes missions de management de transition DSI. Ce type de contexte recoupe potentiellement le vôtre.\n\nVotre annonce reste toutefois assez peu détaillée à ce stade : je serais disposé à un échange court pour clarifier le périmètre réel du poste.\n\nQuelques points à préciser avant d''aller plus loin :\n- Le rôle recouvre-t-il un mandat de pilotage avec autorité de décision, ou une fonction de chef de projet sans latitude managériale ?\n- Qui est le sponsor côté client et quel est le rattachement hiérarchique du poste ?\n- Quelle est la durée envisagée et la date de démarrage ?\n- Le TJM affiché (650 €/j) est-il figé ou ouvert à discussion selon profil ?\n\nCordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "operationnel", "signaux_faibles": ["Intitulé orienté ''chef de projet'' plutôt que mandat exécutif", "Annonce quasi sans contenu (pas de durée, pas de démarrage, pas de contexte)", "Domaine cybersécurité éloigné du cœur de compétence infra/IT ops affiché par Jay"]}, "decision": "no_go"}','executed',NULL,'2026-08-14 07:08:15','2026-08-18 19:22:32',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('3G16_50G','mission_qualification','{"source": "free-work", "external_id": "7185fcd7efc75860", "titre": "Manager de transition Data Privacy & Compliance", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjMHGaZAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"synthese": "Annonce board (Free-Work) très peu détaillée : poste de \"Manager de transition Data Privacy & Compliance\" à Paris, client non nommé, TJM non affiché (plancher board 750€/j), durée et démarrage non précisés — l''annonce ne décrit quasiment rien du périmètre réel ni du mandat.", "motifs": ["<item>L''intitulé pointe vers un rôle de compliance/data privacy (DPO-like), hors du cœur de cible DSI/CTO/DOSI de Jay — pas d''infrastructure, pas d''IT ops, pas de transformation technique mentionnée</item>\n<item>Aucune indication de registre (exécutif vs opérationnel vs technique) ni d''autorité de mandat — l''intitulé \"manager de transition\" est affiché mais rien ne confirme un mandat exécutif plutôt qu''une mission de conformité en appui</item>\n<item>Annonce quasi vide : pas de secteur, pas de taille d''entreprise, pas de trigger de transformation (carve-out, fusion, dette technique) qui caractérise le profil cible</item>\n<item>TJM board non affiché, plancher réseau à 750€/j net à rappeler si le sujet avance, mais ce n''est pas un motif de recommandation</item>\n</motifs>\n<questions>\n<item>Le rôle recouvre-t-il un mandat de manager de transition avec autorité de décision, ou s''agit-il d''un poste de consultant/expert en appui à une DPO ou un DSI déjà en place ?</item>\n<item>Quel est le périmètre exact : mise en conformité RGPD, structuration d''une fonction Data Privacy, gestion de crise (violation de données, audit CNIL), ou pilotage d''un programme de gouvernance data plus large ?</item>\n<item>Quel est le secteur d''activité et la taille de l''organisation cliente ?</item>\n<item>Quelle est la durée envisagée et la date de démarrage souhaitée ?</item>\n<item>Quel est le TJM proposé sur cette mission ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nSur mes missions récentes (Saint-Gobain, MAGUIN-PROMILL), j''ai piloté des sujets de structuration IT et de gouvernance impliquant des enjeux de conformité et de sécurisation des données, en lien avec les équipes métiers et les DSI. Si votre mission de Manager de transition Data Privacy & Compliance s''inscrit dans une logique de structuration ou de mise en conformité d''une fonction data au sein d''une DSI, je peux être positionné.\n\nSeriez-vous disponible pour un échange rapide afin de clarifier le périmètre exact de la mission ?\n\nQuelques points à préciser de mon côté :\n- Le rôle est-il un mandat avec autorité de décision, ou un poste de consultant en appui d''une fonction déjà en place ?\n- Quel est le périmètre : RGPD, gestion de crise, gouvernance data plus large ?\n- Secteur et taille de l''organisation cliente ?\n- Durée et date de démarrage envisagées ?\n- TJM proposé ?\n\nCordialement,\nJayson Angele</brouillon_reponse\">\n<parameter name=\"role_attendu\">indetermine"], "registre": "indetermine", "recommandation": "poursuivre_sous_reserve", "signaux_faibles": ["Intitulé orienté Data Privacy/Compliance, éloigné du cœur de cible DSI/CTO/DOSI infra & transformation IT", "Aucun élément sur l''autorité du rôle (mandat exécutif vs pair/consultant)", "Annonce quasi vide de contenu exploitable — risque fort de rôle de consultant pair plutôt que mandat de manager"], "informations_manquantes": ["Rôle avec autorité décisionnelle ou consultant en appui", "Périmètre exact (RGPD, gestion de crise, gouvernance data)", "Secteur et taille de l''entreprise cliente", "Durée et démarrage", "TJM proposé"]}, "decision": "no_go"}','executed',NULL,'2026-08-14 07:08:34','2026-08-18 19:22:22',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('bjUXmfrU','reply_mail','{"to": "kaley.bridgeman@beverlyshop.info", "subject": "RE: Question for Inovops", "body": "Bonjour Kaley,\n\nMerci pour votre message. Pourriez-vous préciser ce que recouvre votre offre (nature du financement, conditions, et pour quel type de structure) ? Cela me permettra de voir s''il y a une pertinence par rapport à l''activité d''INOVOPS.\n\nDans l''attente de ces précisions.", "mail_from": "kaley.bridgeman@beverlyshop.info", "mail_subject": "Question for Inovops", "mail_received": "2026-08-14T12:38:04Z", "mail_body": "Do you serve enterprise IT leaders across all three locations?\r\n\r\nWe get consulting firms the funding they need to move faster.\r\n\r\nCan I send more info?\r\n\r\n— Kaley Bridgeman", "conversation_id": "AAQkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQAQAJYkwiFoDMVKvki6GiuoHlk="}','rejected',NULL,'2026-08-14 14:05:10','2026-08-18 19:22:15',NULL,'No interest',NULL);
INSERT INTO "pending_actions" VALUES('fsWhqAoh','linkedin_pages_activation','{"pages": [{"slug": "to-taste", "cabinet": "TASTE"}]}','executed',NULL,'2026-08-15 05:50:08','2026-08-18 19:37:57',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('KpMMfV8G','mission_qualification','{"source": "lecercle", "external_id": "8903d6c212a17e7c", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/tresorier-groupe-grand-groupe-de-conseil-3-a-6-mois/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Ceci n''est pas une offre mais un mail d''alerte automatique du Cercle listant des missions correspondant à un mot-clé ; l''unique poste visible dans l''extrait fourni est « Business Architect - Secteur Assurance - 6 mois », sans lien avec un mandat DSI/CTO.", "motifs": ["Le contenu transmis est une notification d''alerte, pas une fiche de mission qualifiée\", \"Le seul intitulé de poste visible (Business Architect, assurance, 6 mois) ne correspond pas au positionnement DSI/CTO/DOSI de Jay\", \"Aucun élément de rôle, d''autorité, de registre ou de contexte de transformation n''est présent pour évaluer un mandat\", \"Le lien pointe vers une mission ''Trésorier Groupe'' dans le conseil, encore un autre intitulé, ce qui confirme que l''annonce est un agrégat d''alertes et non une offre unique</motifs>\n<parameter name=\"questions\">[\"Quelle est la mission précise associée à l''alerte DSI/CTO/DOSI, avec intitulé, contexte client et périmètre ?\", \"S''agit-il d''un mandat de direction (autorité, décision) ou d''une mission de conseil/expertise sans autorité managériale ?\", \"Quel est le TJM proposé au manager de transition sur cette mission (pas le tarif facturé au client) ?\"]"], "brouillon_reponse": "Bonjour,\n\nJe suis intéressé par vos missions de management de transition DSI/CTO/DOSI, mais le contenu reçu semble être un agrégat de plusieurs alertes (Business Architect assurance, Trésorier Groupe...) plutôt qu''une fiche de mission unique correspondant à mon profil.\n\nSeriez-vous disponible pour un échange court afin d''identifier la mission DSI/CTO qui correspond réellement à mon alerte ?\n\nPour avancer, pourriez-vous me préciser : l''intitulé exact et le contexte client de la mission DSI/DOSI visée, s''il s''agit d''un mandat de direction avec autorité de décision ou d''un rôle de conseil, et le TJM proposé sur cette mission ?\n\nCordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["Le contenu fourni ne décrit aucune mission DSI/CTO exploitable, seulement un mail d''alerte générique avec des intitulés hors périmètre\", \"Impossible de distinguer mandat exécutif vs rôle de pair faute de descriptif de poste"]}, "decision": "no_go"}','executed',NULL,'2026-08-15 06:19:59','2026-08-18 19:21:29',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('dIdIHCer','mission_qualification','{"source": "lecercle", "external_id": "971407a01e62731b", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/program-director-it-operational-separation-lead-carve-out-international-groupe-international-12-mois-renouvelables/", "contact_email": null, "qualification": {"synthese": "L''annonce reçue est une notification d''alerte générique du Cercle, pas une fiche de mission : elle liste des titres de projets sans détail sur celui visé (« Program Director IT — Operational Separation Lead, Carve-out, groupe international, 12 mois renouvelables »), sans client nommé, sans lieu, sans TJM ni date de démarrage.", "motifs": ["<item>Le contenu transmis est un extrait d''e-mail d''alerte, pas le corps de l''annonce de mission elle-même — aucune description de périmètre, de rattachement ou de livrables n''est disponible</item>\n<item>Le titre du lien (« carve-out international, 12 mois renouvelables ») correspond fortement au trigger profile cible d''INOVOPS (transformation post-événement, carve-out)</item>\n<item>TJM non affiché à ce stade, plancher EMT 850 €/j net à rappeler le moment venu — non bloquant pour la qualification</item>\n<item>Impossible de statuer sur le rôle attendu (mandat exécutif vs consultant pair) faute de tout descriptif de poste</item>\n</motifs>\n<questions>\n<item>Pouvez-vous partager la fiche complète de la mission « Program Director IT — Operational Separation Lead, Carve-out » (contexte, périmètre, rattachement hiérarchique) ?</item>\n<item>Le rôle est-il un mandat exécutif avec autorité de décision, ou un poste de contribution/conseil auprès d''un titulaire en place ?</item>\n<item>Quel est le TJM proposé et la durée ferme du contrat ?</item>\n<item>Quel est le lieu de la mission et le rythme site/remote attendu ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJe gère l''infrastructure et les opérations IT en contexte de transformation organisationnelle — accompagnement de carve-in/carve-out, structuration de DSI, conduite du changement des équipes IT. La mission « Program Director IT — Operational Separation Lead, Carve-out » sur groupe international correspond directement à ce type d''intervention.\n\nJe serais disponible pour un échange court afin d''aller plus loin sur le contexte du projet.\n\nPour préparer cet échange, pourriez-vous préciser :\n- le périmètre et le rattachement du poste (mandat exécutif avec autorité, ou rôle de contribution auprès d''un titulaire en place) ?\n- le TJM envisagé et la durée ferme du contrat ?\n- le lieu et le rythme site/remote ?\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles\">\n<item>Contenu transmis tronqué / non pertinent (extrait générique d''alerte, pas la fiche de la mission ciblée par le lien)</item>\n<item>Aucun élément de rôle, autorité ou registre disponible pour juger si mandat exécutif ou poste de pair</item>\n</signaux_faibles>\n<recommandation>poursuivre_sous_reserve</recommandation>"]}, "decision": "no_go"}','executed',NULL,'2026-08-15 06:20:13','2026-08-18 19:21:26',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('At9YfTiQ','mission_qualification','{"source": "lecercle", "external_id": "eb1366bf141e5b38", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/maintenance-manager-secteur-industriel-3-a-6-mois/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Il ne s''agit pas d''une offre de mission mais d''un email d''alerte du Cercle listant plusieurs projets potentiels ; le seul intitulé lisible dans le contenu fourni est « Business Architect - Secteur Assurance - 6 mois », sans rapport avec un mandat DSI/CTO, et le lien pointe vers une mission de « Maintenance Manager secteur industriel » distincte.", "motifs": ["Le contenu transmis est un e-mail d''alerte générique, pas une fiche de mission qualifiable\", \"Le seul projet nommé dans le texte (Business Architect - Assurance) ne correspond pas au positionnement DSI/CTO/DOSI de Jay\", \"L''URL de la mission (Maintenance Manager secteur industriel) est incohérente avec le texte de l''alerte, signe que le contenu utile n''a pas été extrait\", \"Aucun élément de rôle, périmètre, autorité ou registre n''est présent pour qualifier quoi que ce soit"], "signaux_faibles": ["Décalage entre l''intitulé du lien (Maintenance Manager) et le texte de l''alerte (Business Architect Assurance)\", \"Contenu tronqué en plein milieu d''une phrase, aucune information exploitable sur le poste réel"], "questions": ["Pouvez-vous partager la fiche de mission complète correspondant à ce lien ou à l''alerte DSI/CTO Groupe ?\", \"S''agit-il bien d''un mandat de DSI/CTO, ou de la mission Business Architect / Maintenance Manager mentionnée dans l''alerte ?\", \"Quel est le périmètre, la durée et le TJM associés à la mission finalement visée ?\""], "brouillon_reponse": "Bonjour,\n\nVotre alerte mentionne plusieurs projets (dont un Business Architect Secteur Assurance) mais le lien renvoie vers une mission de Maintenance Manager secteur industriel : je ne suis pas certain de la mission exacte que vous souhaitez me faire remonter par rapport à mon profil DSI/CTO de transition (pilotage de transformation IT, carve-in/carve-out, structuration d''organisation, gouvernance de programmes).\n\nJe serais disponible pour un échange rapide afin de clarifier le besoin réel derrière cette alerte.\n\nQuelques points à préciser de votre côté :\n- La fiche de mission complète correspondant à l''intitulé DSI/CTO Groupe,\n- S''il s''agit d''un mandat de direction (autorité, décision) ou d''un rôle de conseil/support,\n- Le périmètre, la durée et le TJM envisagés.\n\nBien cordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine"}, "decision": "no_go"}','executed',NULL,'2026-08-15 06:20:25','2026-08-18 19:21:17',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('Hq3EdMcM','mission_qualification','{"source": "free-work", "external_id": "fbb85cdae86479ed", "titre": "PMO Stratégique / Directeur de Projet IT (H/F)", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjNHmMOAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"recommandation": "poursuivre_sous_reserve", "synthese": "Annonce quasi vide : intitulé \"PMO Stratégique / Directeur de Projet IT\" en Centre-Val de Loire, aucun descriptif de contexte client, périmètre, durée ni date de démarrage. Seul le canal (board free-work) et le plancher standard de 750€/j sont connus.", "motifs": ["Intitulé double lecture : ''PMO stratégique'' évoque du pilotage sans autorité directe, ''Directeur de Projet IT'' évoque un mandat avec responsabilité — l''annonce ne permet pas de trancher", "Aucune information sur le contexte de déclenchement (transformation, carve-out, crise IT) qui caractérise les missions ciblées par Jay", "TJM non affiché, plancher board à 750€/j comme sur toute annonce de ce canal — à négocier plus tard, pas un critère de tri ici", "Le canal board correspond au format régie/consultant, pas au mandat exécutif recherché en priorité, mais garde le pipeline actif"], "questions": ["Le poste s''inscrit-il dans un mandat avec autorité de décision (arbitrages budgétaires, hiérarchie IT) ou dans un rôle de PMO en support / recommandation sans levier décisionnel ?", "Quel est le contexte métier du poste : trigger de transformation (fusion, carve-out, dette technique, audit) ou pilotage de portefeuille projet classique ?", "Quelle est la durée visée et la date de démarrage souhaitée ?", "Le poste rapporte à qui (DSI, CTO, COMEX) ?"], "brouillon_reponse": "Bonjour,\n\nJ''ai piloté des missions de PMO stratégique et de direction de projet IT en environnement de transformation — notamment structuration de portefeuille projet et pilotage transverse chez Saint-Gobain (process ITIL) et MAGUIN-PROMILL (PMO transformation digitale), avec un positionnement orienté résultats métier plutôt que reporting seul.\n\nJe serais intéressé pour échanger rapidement sur le contexte de ce poste et voir si mon profil correspond à votre besoin.\n\nQuelques points à préciser de votre côté pour cadrer la discussion :\n- Le rôle s''inscrit-il dans un mandat avec autorité de décision, ou davantage dans un rôle de PMO en accompagnement/recommandation ?\n- Quel est le contexte métier à l''origine du besoin (transformation, projet stratégique, autre) ?\n- Durée visée et horizon de démarrage ?\n\nAu plaisir d''échanger,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["Intitulé ambigu mêlant PMO (potentiellement pair/support) et Directeur de Projet (potentiellement mandat) sans description permettant de lever le doute", "Annonce quasiment vide de contenu factuel, seulement listée dans une alerte automatique — risque de manque de qualification en amont côté cabinet"]}, "decision": "no_go"}','executed',NULL,'2026-08-15 06:25:23','2026-08-18 19:21:10',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('jQno6_cg','mission_qualification','{"source": "free-work", "external_id": "24ec9f8d1db73777", "titre": "Responsable Réseaux, Systèmes et Sécurité H/F", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjNyoZAAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"recommandation": "poursuivre_sous_reserve", "synthese": "Annonce quasi vide : poste de Responsable Réseaux, Systèmes et Sécurité à Metz, publiée sur Free-Work, sans client nommé, sans TJM affiché (plancher board 750€/j), sans durée ni date de démarrage précisées.", "motifs": ["<item>L''intitulé \"Responsable\" suggère un poste opérationnel de management d''équipe infra/réseaux/sécu, pas explicitement un mandat exécutif DSI/CTO — à vérifier</item>\n<item>Aucune indication de périmètre (taille de l''équipe, effectif de l''entreprise, contexte de transformation) permettant de juger l''adéquation avec le positionnement carve-out/fusion/dette technique de Jay</item>\n<item>TJM non affiché : rien n''indique un board pur régie classique, le plancher de 750€/j reste la référence si le canal est confirmé board</item>\n<item>Localisation Metz hors zone géographique préférée mais compatible si hybride ou mission ponctuelle</item>\n</motifs>\n<parameter name=\"questions\">\n<item>Le poste est-il un mandat de management avec autorité de décision (recrutement, budget, arbitrages) ou un rôle de contributeur individuel senior au sein d''une DSI existante ?</item>\n<item>Quel est le contexte : la mission s''inscrit-elle dans une transformation (fusion, carve-out, remédiation post-audit, refonte sécurité) ou s''agit-il d''un remplacement/renfort classique d''équipe ?</item>\n<item>Quelle est la taille de l''organisation IT et de l''entreprise cliente (effectifs, secteur) ?</item>\n<item>Durée de la mission et date de démarrage souhaitée ?</item>\n<item>Modalités : présentiel Metz uniquement ou hybride ?</item>\n</questions>\n<parameter name=\"brouillon_reponse\">Bonjour,\n\nJ''ai piloté des directions Infrastructure/Réseaux/Sécurité dans des contextes de transformation (réorganisation d''équipes techniques, structuration de la sécurité, accompagnement carve-out/fusion), avec un pilotage direct des équipes et des arbitrages budgétaires et organisationnels. Le périmètre Réseaux/Systèmes/Sécurité que vous décrivez recoupe directement ces missions.\n\nJe suis disponible pour un échange rapide afin de voir si le profil correspond à votre besoin.\n\nQuelques points à préciser de votre côté pour cadrer l''échange :\n- Le poste s''inscrit-il dans un mandat avec autorité de décision, ou plutôt en renfort d''une équipe existante ?\n- Le contexte : transformation en cours (fusion, carve-out, remédiation) ou fonctionnement courant ?\n- Taille de l''organisation IT et durée envisagée pour la mission ?\n\nBien cordialement,\nJayson Angele"], "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["<item>Intitulé \"Responsable\" évoque potentiellement un rôle opérationnel de gestion d''équipe plutôt qu''un mandat exécutif de transformation — à clarifier avant d''investir plus de temps</item>\n<item>Annonce quasi sans contenu (aucun descriptif de mission, contexte ou périmètre au-delà du titre) : forte incertitude sur l''adéquation avec le positionnement mandat exécutif</item>\n</signaux_faibles>"]}, "decision": "no_go"}','executed',NULL,'2026-08-15 06:25:38','2026-08-18 19:20:58',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('VTGcBqNW','reminder','{"text": "Pennylane : un justificatif/précision est demandé par l''expert-comptable pour une transaction bancaire du mois d''août 2026. Se connecter à Pennylane pour identifier la transaction concernée et fournir le justificatif.", "start_iso": "2026-08-17T09:00:00", "end_iso": "2026-08-17T09:30:00"}','rejected',NULL,'2026-08-15 08:05:06','2026-08-18 19:20:45',NULL,'déjà fait — traité hors cockpit',NULL);
INSERT INTO "pending_actions" VALUES('qwWzkcQH','reminder','{"text": "Examen PeopleCert (proctoring en ligne) demain mardi 18 août 2026, 14h00-15h15 (UTC+1). Vérifier en amont : matériel, pièce d''identité, connexion, environnement conforme aux consignes (vidéo de préparation disponible). Ne pas répondre à ce mail (no-reply).", "start_iso": "2026-08-18T12:00:00", "end_iso": "2026-08-18T13:30:00"}','rejected',NULL,'2026-08-17 12:05:18','2026-08-18 19:20:39',NULL,'déjà fait — traité hors cockpit',NULL);
INSERT INTO "pending_actions" VALUES('PC85EZuE','mission_qualification','{"source": "lecercle", "external_id": "5fc41cf3a539b4ef", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/program-director-b2b-e-commerce-transformation-acteur-europeen-de-la-distribution/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Cette alerte du Cercle ne décrit aucune mission exploitable : le texte transmis mélange visiblement plusieurs alertes (mention parasite \"Finance / Compta DAF - Secteur Assurance\") et ne contient ni contexte client, ni périmètre, ni durée, ni registre de poste pour la mission DSI visée. Seul un lien pointant vers une offre \"Program Director B2B e-commerce transformation\" laisse supposer un sujet, sans corrélation confirmée avec l''intitulé DSI.", "motifs": ["<item>L''annonce transmise ne contient aucune description de poste exploitable (rôle, périmètre, autorité, secteur)</item>\n<item>Incohérence entre l''intitulé DSI Groupe et le contenu affiché qui évoque Finance/DAF assurance</item>\n<item>Le titre du lien (Program Director B2B e-commerce transformation) ne correspond pas non plus clairement à un mandat DSI/CTO</item>\n<item>TJM non affiché, plancher EMT à 850€/j mentionné par la plateforme seulement à titre indicatif, aucune donnée réelle sur la rémunération</item>\n</motifs>\n<questions>\n<item>Pouvez-vous confirmer l''intitulé exact et le périmètre de la mission derrière ce lien (DSI Groupe, ou Program Director e-commerce, ou une autre offre) ?</item>\n<item>Quel est le secteur d''activité et la taille de l''entreprise cliente ?</item>\n<item>S''agit-il d''un mandat avec autorité de décision (DSI/CTO par intérim) ou d''un rôle de conseil sans autorité hiérarchique ?</item>\n<item>Quelle est la durée envisagée et la date de démarrage souhaitée ?</item>\n<item>Quel est le TJM proposé pour ce mandat ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJe vois passer votre alerte concernant un mandat de Directeur des Systèmes d''Information Groupe, mais le contenu qui m''est parvenu est incomplet et semble mélanger plusieurs offres (une mention Finance/DAF Assurance apparaît, sans lien apparent avec un poste DSI). Je ne suis donc pas en mesure d''évaluer la correspondance avec mon profil de manager de transition DSI/CTO sur cette base.\n\nJe reste intéressé pour échanger si vous pouvez me confirmer le détail de la mission visée : contexte client (secteur, taille), périmètre du mandat, et surtout s''il s''agit d''un mandat exécutif avec autorité de décision plutôt que d''un rôle de conseil.\n\nPourriez-vous me transmettre une fiche de poste complète, avec la durée envisagée et le TJM proposé ? Je pourrai alors vous positionner rapidement sur la pertinence de mon expérience (pilotage DSI, transformation post-fusion/carve-out, restructuration d''équipes IT).\n\nCordialement,\nJayson Angele</brouillon_reponse\">\n<parameter name=\"role_attendu\">indetermine"]}, "decision": "no_go"}','executed',NULL,'2026-08-18 06:20:07','2026-08-18 19:20:33',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('a98XNA2v','mission_qualification','{"source": "lecercle", "external_id": "2922d2ec57d648bc", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/cfo-groupe-6-mois-4/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "L''annonce est un e-mail d''alerte automatique du Cercle qui ne contient quasiment aucune information exploitable : elle mentionne un intitulé « DAF - Secteur Assurance / Prévoyance / Mutuelle » sans rapport avec le DSI recherché, sans client nommé, sans lieu, sans durée, sans TJM ni date de démarrage.", "motifs": ["<item>L''annonce cible en réalité un poste de DAF (Directeur Administratif et Financier) secteur assurance, pas un poste de DSI/CTO — décalage total avec l''alerte et le positionnement de Jay</item>\n<item>Aucun descriptif de mission, de périmètre ou de rôle n''est fourni : impossible d''évaluer autorité, registre ou enjeux</item>\n<item>Absence de TJM affiché : plancher EMT à 850€/j à valider le cas échéant, mais ce n''est pas le motif de l''écart ici</item>\n<item>Le contenu semble être un extrait tronqué ou mal indexé d''une alerte, sans rapport avec le titre du lien (« Directeur des Systèmes d''Information - Groupe »)</item>\n</motifs>\n<questions>\n<item>Confirmez-vous qu''il s''agit bien d''un poste de Directeur des Systèmes d''Information, et non de DAF comme indiqué dans le corps de l''alerte ?</item>\n<item>Quel est le périmètre du mandat (infrastructure, transformation, carve-out, fusion...) et le contexte déclencheur ?</item>\n<item>Quelle est la durée prévisionnelle et la date de démarrage souhaitée ?</item>\n<item>Le mandat est-il assorti d''une autorité de décision (mandat exécutif) ou s''agit-il d''un rôle de conseil sans autorité ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nVotre alerte semble avoir remonté un intitulé qui ne correspond pas au contenu du message (DAF secteur Assurance / Prévoyance / Mutuelle, alors que l''alerte visait un poste de Directeur des Systèmes d''Information Groupe). Avant d''aller plus loin, pourriez-vous confirmer le poste réellement concerné ?\n\nSi un mandat DSI/CTO est bien à pourvoir, je serais disponible pour un échange rapide : mon profil est orienté management de transition DSI sur des transformations post-événement (carve-out, fusion, dette technique critique, audit défavorable) sur des structures mid-market à grandes entreprises.\n\nPour avancer, pourriez-vous préciser :\n- le périmètre exact de la mission et le contexte qui la déclenche,\n- la durée et la date de démarrage envisagées,\n- le niveau de mandat (autorité de décision ou rôle de conseil).\n\nMerci par avance pour ces précisions.\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu\">indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles>\n<item>Contenu de l''annonce incohérent avec son propre titre (DAF vs DSI) — probable erreur d''indexation côté broker</item>\n<item>Aucune information sur le rôle, l''autorité ou le registre attendu, rendant toute qualification impossible en l''état</item>\n</signaux_faibles>"]}, "decision": "no_go"}','executed',NULL,'2026-08-18 06:20:22','2026-08-18 19:20:28',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('_nA-TbYr','mission_qualification','{"source": "lecercle", "external_id": "a584724910857bb6", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/monitoring-officer-services-publics-2/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Notification d''alerte automatique du Cercle listant plusieurs missions correspondant au mot-clé \"DSI Groupe\", sans annonce individualisée exploitable : le contenu visible est un fragment tronqué (\"Finance / Compta DAF - Secteur Assurance / Prévoyance / Mut...\") qui ne décrit ni poste, ni périmètre, ni mandat.", "motifs": ["<item>Le texte fourni est un digest d''alerte, pas une fiche de mission : aucun descriptif de poste, périmètre, rôle ou durée n''est présent</item>\n<item>Le fragment visible (\"DAF - Secteur Assurance\") évoque potentiellement une mission de Directeur Administratif et Financier, pas de DSI/CTO — décalage possible avec le cœur de cible INOVOPS</item>\n<item>Aucun élément ne permet d''évaluer registre, autorité ou trigger de transformation ; rien à qualifier en l''état</item>\n<item>TJM non affiché — mention seule, pas un motif d''écartement en soi</item>\n</motifs>\n<parameter name=\"questions\">\n<item>Pouvez-vous partager la fiche de poste complète correspondant à cette annonce (intitulé exact, missions, périmètre) ?</item>\n<item>S''agit-il bien d''un mandat de Directeur des Systèmes d''Information, ou l''alerte a-t-elle remonté une mission DAF/Finance par erreur ?</item>\n<item>Quel est le format d''engagement envisagé (mandat exécutif, temps plein, durée) ?</item>\n</questions>\n<parameter name=\"brouillon_reponse\">Bonjour,\n\nVotre alerte semble avoir remonté un extrait mêlant plusieurs profils (DAF / Assurance) et je ne retrouve pas, dans ce que j''ai sous les yeux, de descriptif clair du poste de DSI visé. Je préfère vous le dire directement plutôt que de vous répondre à côté.\n\nJe suis manager de transition DSI/CTO, avec des mandats récents en pilotage de transformation SI (Saint-Gobain, MAGUIN-PROMILL) sur des enjeux de structuration IT, gouvernance et accompagnement des équipes en transformation.\n\nPourriez-vous me transmettre la fiche de poste complète correspondant à cette alerte \"DSI Groupe\" ? Je pourrai alors vous dire précisément en quoi mon profil colle au périmètre attendu, et on pourra caler un échange court si ça matche.\n\nCordialement,\nJayson Angele"], "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["<item>Contenu de l''annonce quasi inexploitable — semble être un digest multi-missions tronqué plutôt qu''une offre unique</item>\n<item>Mention \"DAF - Secteur Assurance\" incohérente avec un poste de DSI, suggère une erreur de matching de l''alerte</item>\n</signaux_faibles>"]}, "decision": "no_go"}','executed',NULL,'2026-08-18 06:20:37','2026-08-18 19:20:20',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('Bd7df6VX','mission_qualification','{"source": "lecercle", "external_id": "f6e4dd6e9bc4c604", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/consultant-sap-fi-co-bilingue-anglais-senior-groupe/", "contact_email": null, "qualification": {"recommandation": "poursuivre_sous_reserve", "synthese": "Alerte broker (Le Cercle/EMT) quasi vide : intitulé \"Directeur des Systèmes d''Information - Groupe\" côté finance/compta, secteur assurance/prévoyance/mutuelle, mais aucune description de mission, périmètre, durée ni TJM n''est fournie — le lien pointe même vers une fiche \"consultant SAP FI-CO\" sans rapport apparent avec l''intitulé.", "motifs": ["<item>L''intitulé correspond bien à l''alerte DSI Groupe, ce qui justifie de ne pas écarter d''emblée</item>\n<item>Incohérence forte entre l''intitulé (DSI Groupe) et le lien fourni (consultant SAP FI-CO bilingue anglais) — signal de mauvais routage ou de mission mal qualifiée par le broker</item>\n<item>Aucun élément sur le rôle (mandat exécutif vs consultant), le périmètre ou la durée : impossible d''évaluer l''adéquation au positionnement DSI/CTO 6-9 mois</item>\n<item>TJM non affiché : à ce stade normal sur ce canal, à traiter en échange, pas un motif de retrait</item>\n</motifs>\n<parameter name=\"questions\">\n<item>Le lien renvoie vers une mission \"Consultant SAP FI-CO\" : s''agit-il bien de la même mission que \"Directeur des Systèmes d''Information - Groupe\", ou d''une erreur de correspondance dans l''alerte ?</item>\n<item>Quel est le périmètre exact du poste DSI Groupe : mandat exécutif avec autorité de décision, ou mission de conseil/support sans autorité ?</item>\n<item>Quelle est la durée envisagée et la date de démarrage souhaitée ?</item>\n<item>Quel est le TJM proposé pour ce mandat ?</item>\n</questions>\n<parameter name=\"brouillon_reponse\">Bonjour,\n\nJe suis manager de transition DSI/CTO, avec une expérience récente de pilotage de transformation SI en environnement groupe (structuration IT, gestion de dette technique, accompagnement des équipes dans des contextes de transformation post-fusion/carve-out). Le profil \"Directeur des Systèmes d''Information - Groupe\" en secteur assurance/prévoyance correspond à ce type de mandat.\n\nJe serais disponible pour un échange rapide afin de voir si le poste correspond à mon profil.\n\nQuelques points à préciser de votre côté :\n- Le lien transmis pointe vers une fiche \"Consultant SAP FI-CO bilingue anglais\" — pouvez-vous confirmer qu''il s''agit bien de la même mission que celle intitulée DSI Groupe ?\n- Le périmètre du mandat (autorité décisionnelle, rattachement, taille des équipes) ?\n- La durée prévue et le démarrage souhaité ?\n- Le TJM envisagé ?\n\nCordialement,\nJayson Angele"], "role_attendu": "indetermine", "registre": "indetermine", "signaux_faibles": ["<item>Le lien de l''annonce renvoie vers une mission \"Consultant SAP FI-CO\" sans rapport apparent avec l''intitulé DSI Groupe — possible erreur de matching de l''alerte</item>\n<item>Aucune description de mission ni de rôle fournie au-delà de l''intitulé et du secteur</item>\n</signaux_faibles>"]}, "decision": "no_go"}','executed',NULL,'2026-08-18 07:06:10','2026-08-18 19:23:30',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('6uXX3pOW','mission_qualification','{"source": "lecercle", "external_id": "6eeaded8a3d59cdc", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/ai-data-consultant-plateforme-de-services-aux-professionnels-6-a-8-mois/", "contact_email": null, "qualification": {"recommandation": "ecarter", "synthese": "Alerte automatique du Cercle qui liste en vrac des résultats de recherche ne correspondant pas au libellé de l''alerte : le seul descriptif fourni est « DAF - Secteur Assurance / Prévoyance / Mut... », soit un poste de Directeur Administratif et Financier, pas de DSI/CTO. Aucun contexte client, périmètre, durée ni TJM réel n''est communiqué pour une mission DSI.", "motifs": ["Le contenu affiché parle d''un poste DAF (Finance/Compta), pas DSI/CTO — hors cœur de cible INOVOPS\", \"Aucune information sur le rôle, l''autorité, le périmètre ou la durée d''une mission DSI n''est présente dans l''annonce\", \"Il s''agit d''un email d''alerte agrégeant plusieurs offres, pas d''une fiche de mission individualisée\", \"TJM non affiché, simple mention du plancher EMT (850€/j), ce qui est normal à ce stade et ne pèse pas dans la décision"], "signaux_faibles": ["Le contenu ne correspond pas à l''intitulé de l''alerte (DAF vs DSI)\", \"Aucun signal sur le registre (technique/opérationnel/exécutif) ni sur le rôle attendu (mandat vs consultant)"], "questions": ["Pouvez-vous transmettre la fiche de mission complète correspondant spécifiquement au poste de Directeur des Systèmes d''Information ?\", \"Quel est le périmètre exact du poste DSI visé (taille de l''organisation IT, effectifs managés, budget) ?\", \"Le mandat est-il de type direction exécutive (autorité de décision) ou support/conseil auprès d''un DSI en poste ?"], "brouillon_reponse": "Bonjour,\n\nLe contenu reçu ne semble pas correspondre à l''intitulé de l''alerte : vous mentionnez un poste DAF (secteur Assurance/Prévoyance/Mutuelle), là où l''alerte visait un poste de Directeur des Systèmes d''Information Groupe. Je me tiens à votre disposition dès qu''une mission DSI/CTO en gestion de transition sera disponible — mon profil couvre la direction de transformation IT (carve-out, fusion, redressement de dette technique, structuration de DSI) sur des mandats de 6 à 9 mois.\n\nSeriez-vous en mesure de me confirmer s''il existe bien une offre DSI derrière cette alerte, ou de me renvoyer la fiche correspondante ? Je serais disponible pour un échange court si c''est le cas.\n\nDans l''attente, quelques points à préciser le cas échéant : le périmètre du poste (taille de l''organisation IT, effectifs, budget), la nature du mandat (direction exécutive avec autorité de décision, ou rôle de conseil), ainsi que la durée et les modalités de démarrage.\n\nCordialement,\nJayson Angele", "role_attendu": "indetermine", "registre": "indetermine"}, "decision": "no_go"}','executed',NULL,'2026-08-18 07:06:25','2026-08-18 19:20:13',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('wq1fKK7d','mission_qualification','{"source": "lecercle", "external_id": "eca359d45a90269f", "titre": "Résultats de l’alerte de missions correspondant à « Directeur des Systèmes d''Information - Groupe »", "url": "https://lecercle.in/mission/daf-secteur-assurance-prevoyance-mutuelle-8-mois/", "contact_email": null, "qualification": {"synthese": "Alerte generique du Cercle : le titre pointe vers un poste DAF (Directeur Administratif et Financier), secteur assurance/prévoyance/mutuelle, alors que l''alerte suivie est \"DSI Groupe\" — l''annonce elle-même ne décrit quasiment rien du poste réel (pas de contexte, pas de périmètre, pas de durée, pas de TJM, client non nommé).", "motifs": ["<item>Le contenu transmis est un extrait d''alerte, pas une fiche de mission : aucune description du périmètre, des enjeux ou de l''autorité attendue</item>\n<item>Le titre affiché (DAF) ne correspond pas au positionnement DSI/CTO de Jay ni à l''alerte qui l''a déclenché — soit une erreur de matching du Cercle, soit une confusion de canal</item>\n<item>Secteur assurance/mutuelle cohérent avec le profil cible, mais rien ne confirme qu''il s''agisse bien d''un mandat DSI</item>\n<item>TJM non affiché : à négocier plus tard, plancher EMT 850€/j à rappeler le moment venu, pas un critère de qualification ici</item>\n</motifs>\n<questions>\n<item>Confirmez-vous qu''il s''agit bien d''une mission de Directeur des Systèmes d''Information, et non d''un poste de DAF comme le titre l''indique ?</item>\n<item>Quel est le périmètre exact du poste (taille de la DSI, effectifs managés, contexte de transformation) ?</item>\n<item>Quelle est la durée du mandat et la date de démarrage envisagée ?</item>\n<item>Le poste s''inscrit-il dans un mandat avec autorité de décision (interim exec) ou un rôle de conseil/support ?</item>\n</questions>\n<brouillon_reponse\">Bonjour,\n\nJe suis intéressé par cette opportunité dans le secteur assurance/mutuelle — j''ai piloté des transformations SI dans des environnements réglementés comparables (gouvernance IT, structuration post-événement), un contexte où mon profil de manager de transition DSI/CTO trouve à s''exprimer pleinement.\n\nSeriez-vous disponible pour un échange rapide afin de clarifier le positionnement de cette mission ?\n\nQuelques points à préciser de mon côté : le titre indiqué (DAF) semble différer de l''intitulé DSI attendu — pourriez-vous confirmer la nature exacte du poste ? Je serais également intéressé de connaître le périmètre du mandat (taille d''équipe, enjeux de transformation), sa durée et le type de mandat (exécutif avec autorité de décision, ou mission de conseil).\n\nCordialement,\nJayson Angele</brouillon_reponse>\n<role_attendu>indetermine</role_attendu>\n<registre>indetermine</registre>\n<signaux_faibles>\n<item>Incohérence entre le titre de la fiche (DAF) et l''alerte suivie (DSI) — signale une possible erreur de diffusion du broker</item>\n<item>Annonce quasi vide de contenu descriptif, ne permet pas d''évaluer le registre (technique/opérationnel/exécutif) ni le rôle réel</item>\n</signaux_faibles>\n<recommandation>poursuivre_sous_reserve</recommandation>"]}, "decision": "no_go"}','executed',NULL,'2026-08-18 07:06:40','2026-08-18 19:19:40',NULL,NULL,NULL);
INSERT INTO "pending_actions" VALUES('U67yVAdX','reminder','{"text": "Corriger le job CI \"Lint, types et tests\" en échec sur ai-agent-steroid (PR feat(alertes) : une mission par offre, son texte, son titre, et sa source — commit 58f33c0). Vérifier les annotations du job avant de merger.", "start_iso": "2026-08-19T09:00:00", "end_iso": "2026-08-19T10:00:00"}','rejected',NULL,'2026-08-18 14:05:07','2026-08-18 19:19:27',NULL,'déjà fait — traité hors cockpit',NULL);
INSERT INTO "pending_actions" VALUES('9Dg1CS4A','mission_qualification','{"source": "free-work", "external_id": "fa5aae840cc2b84e", "titre": "Directeur de Programme IT – Transformation & Déménagement de sites (H/F)", "url": "https://outlook.office365.com/owa/?ItemID=AAMkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQBGAAAAAAATbMc9knsQRIAnAvTKh8PnBwBjh9rTbUXdTKA8%2FfOASe6cAATdIxe3AABjh9rTbUXdTKA8%2FfOASe6cAAjPpQQkAAA%3D&exvsurl=1&viewmodel=ReadMessageItem", "contact_email": null, "qualification": {"recommandation": "poursuivre_sous_reserve", "synthese": "Directeur de Programme IT pour une transformation avec déménagement de sites, à La Défense. Client non nommé, durée et démarrage non précisés, TJM affiché 700€/j.", "motifs": ["<motifs>Intitulé \"Directeur de Programme\" suggère un mandat, mais périmètre (transfo + déménagement) reste vague</motifs>\n<motifs>TJM affiché 700€/j, sous le plancher board net (750€) — à renégocier avant tout envoi de CV</motifs>\n<motifs>Aucune indication sur secteur, taille client ni trigger de transformation — hors ou dans cible à vérifier</motifs>\n</motifs>\n<questions>\n<questions>Quel est le secteur d''activité et la taille du client final ?</questions>\n<questions>Quel est le périmètre exact du programme (IT seul, ou aussi facilities/RH/organisation) ?</questions>\n<questions>Le TJM de 700€/j est-il négociable à la hausse ?</questions>\n<questions>Quelle est la durée prévue de la mission et la date de démarrage ?</questions>\n<questions>Le rôle inclut-il une autorité de décision (mandat) ou est-il en support d''un DSI/sponsor existant ?</questions>\n</questions>\n<role_attendu>indetermine</role_attendu>\n<registre>operationnel</registre>\n<signaux_faibles>\n<signaux_faibles>TJM sous le plancher board net (700€ vs 750€ plancher)</signaux_faibles>\n<signaux_faibles>Aucun descriptif détaillé au-delà de l''intitulé — périmètre réel du poste inconnu</signaux_faibles>\n</signaux_faibles>"]}}','rejected',NULL,'2026-08-19 06:18:49','2026-08-28 10:09:10',NULL,'Non retenu',NULL);
INSERT INTO "pending_actions" VALUES('HxDsqy3Q','mission_qualification','{"source": "lecercle", "external_id": "bcc474c296039405", "titre": "SI / IT Chief Technology Officer - Secteur SaaS - 6 mois Pays-Bas RENOIR [Logo de Finatal]", "url": "https://lecercle.in/mission/cfo-secteur-b2b-software-saas/", "contact_email": null, "qualification": {"recommandation": "poursuivre_sous_reserve", "synthese": "Mandat CTO/DSI intérim 6 mois, secteur SaaS B2B, Pays-Bas, via cabinet Renoir/Finatal. Lieu précis, périmètre et TJM non détaillés dans l''annonce.", "motifs": ["Intitulé CTO = registre exécutif, cohérent avec le positionnement DSI/CTO d''INOVOPS", "Secteur SaaS hors périmètre cible habituel (industrie/services/santé/banque/assurance)", "Localisation Pays-Bas : hors zone géographique préférée, à valider (déplacement, remote)"], "questions": ["Quel est le contexte de la mission (croissance, carve-out, post-fusion, redressement) ?", "Le mandat est-il exécutif avec autorité de décision, ou un rôle de conseil/support au CTO en place ?", "Le format est-il full remote, hybride ou 100% on-site aux Pays-Bas ?", "Quel est le TJM proposé pour ce mandat EMT ?", "Quelle est la taille de l''entreprise cliente (effectifs, CA) ?"], "role_attendu": "indetermine", "signaux_faibles": ["Secteur SaaS ne correspond pas aux secteurs primaires visés (industrie, services, santé, banque, assurance)", "Aucun détail sur le trigger de transformation (carve-out, fusion, dette technique) habituellement recherché", "TJM non affiché, à négocier avec le cabinet en même temps que le CV"]}}','rejected',NULL,'2026-08-19 06:18:58','2026-08-28 10:07:57',NULL,'Hors périmétre',NULL);
INSERT INTO "pending_actions" VALUES('0GyaO94I','mission_qualification','{"source": "cabinet:reactive-executive", "external_id": "f92e8e57fc63af17", "titre": "DSI de Transition / Manager Gouvernance SI de transition H/F", "url": "https://www.reactive-executive.com/mission/", "contact_email": null, "qualification": {"synthese": "Mandat de DSI de transition / gouvernance SI porté par un cabinet EMT (Reactive Executive), positionnement conforme au cœur de cible INOVOPS. Lieu, durée, démarrage et TJM non précisés.", "motifs": ["Intitulé exécutif (DSI de transition), cohérent avec le mandat exec visé par Jay", "Canal EMT reconnu, plancher net 850€/j applicable si TJM confirmé au-dessus", "Aucune précision sur périmètre, secteur client ou durée à ce stade"], "questions": ["Quel est le secteur et la taille de l''entreprise cliente finale ?", "Quel est le contexte déclencheur de la mission (carve-out, fusion, dette technique, audit défavorable) ?", "Quelle est la durée prévisionnelle du mandat et la date de démarrage ?", "Le TJM proposé est-il aligné avec le marché EMT DSI (1200-2000€/j) ?", "Mandat de DSI avec autorité décisionnelle pleine, ou rôle de gouvernance en support d''un DSI en place ?", "Quel est le lieu de la mission (site, remote, hybride) ?"], "role_attendu": "indetermine", "registre": "executif", "recommandation": "poursuivre_sous_reserve", "signaux_faibles": ["Intitulé double (DSI de transition / Manager Gouvernance SI) pouvant recouvrir un rôle de gouvernance sans autorité pleine de DSI", "Descriptif quasi inexistant : aucun périmètre, secteur ni contexte de déclenchement mentionné"], "informations_manquantes": ["Secteur et taille du client final", "Contexte déclencheur de la mission", "Durée et date de démarrage", "TJM proposé", "Périmètre exact de la mission et niveau d''autorité", "Lieu / modalité de travail"]}}','rejected',NULL,'2026-08-20 10:41:23','2026-08-28 10:07:31',NULL,'Non retenu',NULL);
