INSERT INTO "pending_actions" VALUES('-GJLbkgN','mission_qualification','{"source": "lecercle", "external_id": "a621666221c2104a", "titre": "Digital CTO / VP Engineering - Secteur du Digital - 6 mois minimum - 1090 € par jour Paris La Défense - 92 -…", "url": "https://lecercle.in/mission/responsable-credit-management-recouvrement-groupe-3-mois/", "contact_email": null, "qualification": {"synthese": "Mandat Digital CTO / VP Engineering, secteur Digital, à Paris La Défense (92), 6 mois minimum, TJM affiché 1090 €/j.", "motifs": ["Intitulé CTO/VP Engineering = registre exécutif, cohérent avec le positionnement mandat interim", "Durée 6 mois minimum correspond au format cible (6-9 mois)", "TJM affiché 1090 €/j, sous la cible EMT (1100) mais au-dessus du plancher (850)"], "questions": ["Client final : secteur digital précisément - éditeur, agence, marketplace, scale-up ?", "Taille de l''entreprise et effectif des équipes tech encadrées ?", "Contexte du mandat : création de poste, remplacement, transformation post-événement ?", "Rattachement hiérarchique et niveau d''autorité réel sur les équipes engineering ?", "Lieu exact : full on-site La Défense ou hybride ?"], "role_attendu": "indetermine", "registre": "executif", "informations_manquantes": ["Nom et profil du client final", "Contexte déclencheur de la mission (trigger)", "Rattachement hiérarchique et autorité", "Modalités on-site/remote précises", "Date de démarrage"], "signaux_faibles": ["Intitulé double CTO/VP Engineering peut masquer un rôle plus opérationnel/pair que mandat exécutif plein", "Secteur ''Digital'' est vague, hors des secteurs primaires ciblés (industrie/services/santé/banque/assurance)"], "recommandation": "poursuivre_sous_reserve"}}','rejected',NULL,'2026-08-27 07:01:43','2026-08-28 09:45:28',NULL,'déjà traité',NULL);
INSERT INTO "pending_actions" VALUES('gm4uloRA','reply_mail','{"to": "Billy.Precup@access-avidity.com", "subject": "RE: Service Management Process Manager – Remote Long Term Mission ", "body": "Bonjour Billy,\n\nMerci pour cette proposition. Le rôle m''intéresse — le périmètre ITIL V3 process management sur un environnement Network Managed Services correspond à mon expertise (pilotage de processus de service management, audits, maturité, KPI/reporting).\n\nQuelques points avant de vous transmettre mon CV :\n\n- Positionnement TJM : dans une fourchette 850–1 050 € HT/jour selon le cadrage exact de la mission (durée, charge de travail, niveau de responsabilité — pilotage vs. exécution).\n- Sur la partie Juniper SD-WAN : mon expertise est confirmée sur ITIL V3/process management à grande échelle sur environnements réseau complexes ; pourriez-vous préciser le niveau d''exposition SD-WAN/Juniper réellement attendu (hands-on technique ou pilotage de processus sur cet environnement) ?\n- Durée de la mission et date de démarrage souhaitée ?\n- Le mandat est-il positionné comme un rôle de pilotage/manager, ou en support d''une équipe déjà en place ?\n\nJe vous transmets mon CV dès que j''ai ces précisions.", "mail_from": "Billy.Precup@access-avidity.com", "mail_subject": "Service Management Process Manager – Remote Long Term Mission ", "mail_received": "2026-08-27T09:43:37Z", "mail_body": "Good day,\r\n\r\nI am currently recruiting for a Service Management Process Manager position supporting our clients Network Managed Services environment across Brussels and Luxembourg.\r\n\r\nThe role is focused on ITIL-based service/process management within a large-scale network environment, covering process design and implementation, continuous improvement, audits, KPI/metrics reporting, and service maturity. Strong exposure to SD-WAN and network infrastructure is important, with Juniper experience particularly relevant.\r\n\r\nActivities:\r\n• Develop, implement and manage complex processes within the organisation in accordance with the Service Management Model based on ITIL V3 or DevOps best practices\r\n• Proactive supporting staff in everyday operations from the perspective of process management and improvement to deliver service of high quality\r\n• Constantly reviewing procedures and application of them to achieve higher levels of maturity\r\n• Perform or assist in performing process audits\r\n• Identify and drive process improvements\r\n• Measure and report on process performance\r\n• Develop, Manage and monitor annual workplan in the domain of service management processes\r\n• Write specifications for the development of the process supporting tools 3.\r\n\r\nRequirements:\r\n• Education : BAC + 5 or more is an asset\r\n• At least 5 years of experience in ITIL V3 process design and implementation\r\n• Preferably ITIL V3 or more certified\r\n• Juniper SD WAN\r\n\r\nSkills required:\r\n• Good knowledge of one or several IT domains\r\n• Solid documentation skills\r\n• Strong organisational and analytical skills\r\n• Strong interpersonal skills.\r\n• Working knowledge, written and spoken, of English required. French desirable.\r\n\r\nIf the role looks of interest, please send me your latest CV and let me know the daily rate you seek for new long term missions on a remote basis.\r\n\r\nTo note: this position requires the individual to be based in an EU country and hold an EU passport.\r\n\r\nBest,\r\n\r\n\r\n[cid:image001.png@01DD364A.F4B2EEF0]\r\n\r\nMember of The Association of Professional Staffing Companies (APSCo) The information in this email is confidential and is intended solely for the addressee. Access to this email by anyone else is unauthorised. If you are not the intended recipient, you must not read, use or disseminate the information. Any views expressed in this message are those of the individual sender, except where the sender specifically states them to be the views of Access Avidity Ltd.", "conversation_id": "AAQkADA1MWU5NDk2LTY1YjktNGMwMy05ZmFiLWFlOTZlMTk4MTU1YQAQAAbKY8_e5UDjmUsJbLKqAOY="}','rejected',NULL,'2026-08-27 10:05:11','2026-08-28 09:45:08',NULL,'déjà traité',NULL);
INSERT INTO "pending_actions" VALUES('95lmZUJW','mission_qualification','{"source": "free-work", "external_id": "664031", "titre": "CTO / VP engineering — freelance (6 mois minimum) — Paris La Défense", "url": "https://www.free-work.com/fr/tech-it/job-mission/directeur-des-nouvelles-technologies-directeur-technique-cto/cto-vp-engineering-freelance-6-mois-minimum-paris-la-defense", "contact_email": null, "qualification": {"synthese": "VP Engineering freelance chez éditeur logiciel B2B international, R&D ~200 pers. (France + Europe de l''Est), réorganisée en 4 pôles. Mission 6 mois, Paris La Défense, 1090€/j, démarrage 14/09/2026.", "motifs": ["Rôle de VP Engineering au sein d''une R&D réorganisée = poste à autorité opérationnelle réelle, pas de la pure conso", "TJM affiché 1090€/j via board : sous la cible EMT (1100) mais au-dessus du plancher board (750), à négocier", "Contexte éditeur B2B international avec centre offshore Europe de l''Est : proche du profil transformation post-réorg visé"], "questions": ["Le poste est-il rattaché directement au nouveau responsable R&D avec autorité managériale sur un des 4 pôles, ou en support/staff ?", "Quel est le périmètre exact du VP Engineering : combien de personnes/équipes sous sa responsabilité directe ?", "Quel est le motif de la réorganisation (dette technique, fusion, changement de gouvernance) et quels sont les livrables attendus sur 6 mois ?", "Le tarif de 1090€/j est-il négociable à la hausse pour un profil senior avec expérience carve-out/transformation ?"], "role_attendu": "manager_mandate", "registre": "executif", "recommandation": "poursuivre_sous_reserve", "signaux_faibles": ["Canal board (Free-Work) : tarif généralement moins négociable qu''en direct ou EMT", "Descriptif tronqué (\"…\") : périmètre réel et autorité du poste à confirmer avant d''aller plus loin"]}}','rejected',NULL,'2026-08-27 10:41:49','2026-08-28 09:42:41',NULL,'déjà traité',NULL);
