INSERT INTO "pending_actions" VALUES('fGTC64jJ','mission_qualification','{"source": "free-work", "external_id": "b1763387b1cd8511", "titre": "IT Risk Manager de la DSI", "url": "https://www.free-work.com/fr/tech-it/job-mission/autre/it-risk-manager-de-la-dsi", "contact_email": null, "qualification": {"synthese": "Consultant risques IT au sein de l''équipe Contrôles et Risques de la DSI, contexte SAFe, pour garantir la conformité des équipes DSI. Île-de-France, 12 mois, 480 €/j.", "motifs": "Rôle de consultant contributeur en équipe Contrôles et Risques, pas de mandat de pilotage ou d''autorité.\nRegistre opérationnel/technique (conformité, contrôles), très en dessous du positionnement DSI/CTO exécutif.\nTJM à 480 €/j, très sous le plancher board (750 €/j net), écart massif non négociable à ce niveau.", "questions": "Quel est le périmètre exact des livrables attendus sur les 12 mois ?\nLe poste reporte-t-il à un RSSI, un DSI ou un directeur des risques ?\nY a-t-il une dimension de pilotage d''équipe ou uniquement de contribution individuelle ?\nLe TJM affiché est-il négociable ou fixe côté client ?", "signaux_faibles": "Intitulé \"IT Risk Manager\" mais descriptif décrit un rôle de consultant accompagnement, pas de management.\nAucune mention d''autorité décisionnelle ou de mandat exécutif dans le texte.\nTJM très bas (480 €/j) pour une mission longue (12 mois), signal de positionnement junior/mid du poste.", "role_attendu": "consultant_pair", "registre": "operationnel", "recommandation": "ecarter", "confiance": 75, "en_quoi_consiste": "Le consultant rejoint l''équipe Contrôles et Risques de la DSI de R&S Telecom, en interface avec l''ensemble de la DSI opérant en agile à l''échelle (SAFe). Le rôle consiste à accompagner cette équipe dans le suivi du respect, par les collaborateurs DSI, de la politique de conformité et de contrôle — une posture d''appui, pas de pilotage exécutif. Le descriptif s''arrête net sur la conformité, sans détail sur le périmètre exact des contrôles, les effectifs encadrés ou le rattachement. Rythme sur site non précisé, mission de 12 mois sans date de démarrage donnée.", "tenants_aboutissants": "", "non_dit": ["Intitulé \"Manager\" pour une mission qui \"accompagne\" une équipe existante — posture d''appui, pas de pilotage.", "480 €/j sur 12 mois, très en dessous du plancher board (750 €/j), pour un rôle affiché \"Manager\"."], "base_confiance": "sur descriptif complet", "faits": "480 €/j — SOUS le plancher 750 €/j · Île-de-France · 12 mois"}}','pending',NULL,'2026-09-13 06:22:02',NULL,NULL,NULL,NULL);
